& {\left[\left\|s_{\psi}\left(\theta_{t}, x, t\right)-\nabla_{\theta_{t}} \log p_{t \mid 0}\left(\theta_{t} \mid \theta_{0}\right)\right\|^{2}\right] \mathrm{d} t }
\end{aligned}

